
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_br89_explicit_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_br89_explicit", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.417191341471349e+00, -3.405279424033380e+00, -3.383399270860104e+00, -3.343510758780152e+00, -3.272225124061282e+00, -3.148954503665887e+00, -2.946078739032600e+00, -2.637149119754526e+00, -2.221136744795216e+00, -1.737955566785781e+00, -1.229365398562437e+00, -7.473746435766747e-01, -5.752457384871825e-01, -5.038177048040703e-01, -3.968150197464491e-01, -2.754228989863584e-01, -1.794081048891170e-01, -1.169536548997492e-01, -7.707686825082580e-02, -5.173800174510623e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


